window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"8bPDmsM6k_c","speaker":"Khurelsukh Ukhnaa","role":"President","country":"Mongolia","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=8bPDmsM6k_c","date":"20260922","title":"🇲🇳 Mongolia - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1332,"words":2935,"counts":{"claims":37,"promises":1,"attacks":0},"topics":[{"topic":"UN governance","share":0.1908,"seconds":254},{"topic":"Mongolia environment","share":0.1592,"seconds":212},{"topic":"Mongolia history","share":0.1002,"seconds":134},{"topic":"Mongolia UN role","share":0.0678,"seconds":90},{"topic":"Mongolia foreign relations","share":0.0646,"seconds":86},{"topic":"Mongolia sovereignty","share":0.0594,"seconds":79},{"topic":"Mongolia military","share":0.0588,"seconds":78},{"topic":"Gender equality","share":0.0533,"seconds":71},{"topic":"International security","share":0.0522,"seconds":70},{"topic":"Mongolia culture","share":0.0496,"seconds":66},{"topic":"Women in conflict","share":0.0492,"seconds":66},{"topic":"Mongolia agriculture","share":0.0482,"seconds":64},{"topic":"Mongolia trade","share":0.0467,"seconds":62}],"timeline":[[0,68,null],[69,143,"UN governance"],[146,208,"UN governance"],[209,274,"Mongolia history"],[275,344,"International security"],[352,430,"UN governance"],[431,521,"Mongolia UN role"],[521,600,"Mongolia military"],[600,666,"Women in conflict"],[667,729,"Mongolia trade"],[732,814,"Mongolia environment"],[815,875,"Mongolia environment"],[876,946,"Mongolia environment"],[948,1012,"Mongolia agriculture"],[1013,1100,"Mongolia foreign relations"],[1106,1177,"Gender equality"],[1178,1244,"Mongolia culture"],[1245,1324,"Mongolia sovereignty"],[1329,1397,"Mongolia history"],[1398,1437,"UN governance"]],"stances":{"UN governance":"Khurelsukh Ukhnaa congratulates the new president and expresses Mongolia's support for the UN theme and its central role in global cooperation.","Mongolia history":"Khurelsukh Ukhnaa advocates for a multi-pillared international relations principle inspired by the historical Pax Mongolica to foster coexistence and strengthen multilateral cooperation.","International security":"Khurelsukh Ukhnaa states that over 90 armed conflicts are destabilizing global peace, disrupting supply chains, and undermining the post-WWII international order.","Mongolia UN role":"Khurelsukh Ukhnaa announces Mongolia's official candidacy for a non-permanent seat on the UN Security Council for the 2048-2049 term and expresses gratitude for the UN's contributions to Mongolia's development.","Mongolia military":"Khurelsukh Ukhnaa states that Mongolia has made tangible contributions to global peace and security through active participation in UN peacekeeping operations and high rates of women's representation.","Women in conflict":"Khurelsukh Ukhnaa highlights Mongolia's contributions to global peace by women and announces plans to host an international conference on their participation in UN peacekeeping operations.","Mongolia trade":"Khurelsukh Ukhnaa emphasizes the need for landlocked developing countries to align programs with national agendas and calls for international financial support, while noting that only 36% of SDGs are on track and global military spending has reached a record high.","Mongolia environment":"Khurelsukh Ukhnaa states that Mongolia has achieved 68.8% of the Sustainable Development Goals and is implementing national policies to address climate change and environmental protection.","Mongolia agriculture":"Khurelsukh Ukhnaa positions Mongolia's rangeland initiative as a landmark global movement essential for climate resilience and food security.","Mongolia foreign relations":"Khurelsukh Ukhnaa states that Mongolia consistently adheres to resolving conflicts through diplomacy and multilateral dialogue while maintaining friendly regional relations.","Gender equality":"Khurelsukh Ukhnaa highlights Mongolia's history of hosting international women's events and expresses confidence that the upcoming World Women Parliamentarians Forum will advance gender equality.","Mongolia culture":"Khurelsukh Ukhnaa highlights Mongolia's leadership in preserving cultural heritage and its recent international recognitions.","Mongolia sovereignty":"Khurelsukh Ukhnaa asserts that the historical contributions of Mongolian nomadic civilization serve as a foundation for modern efforts to safeguard peace and stability."},"claims":[{"t":92,"quote":"This session of the general assembly is convening on the eve of the 65th anniversary of Mongolia's full-fledged membership in the United Nations.","topic":"UN governance","kind":"fact"},{"t":103,"quote":"In 1961, Mongoya made history by raising its national flag with the golden soybo at the United Nations and becoming the 101st member of the United Nations","topic":"UN governance","kind":"fact"},{"t":146,"quote":"Mongols say if you do your best, fate will do the rest.","topic":"UN governance","kind":"fact"},{"t":151,"quote":"The United Nations is an organization based on the trust and commitment of each member state","topic":"UN governance","kind":"fact"},{"t":231,"quote":"Eight centuries ago, our ancestors established the great Pax Mongolica, promoting for the first time the idea to the world that nations could mutually recognize one another's values and that peoples of diverse civilizations and faiths could coexist.","topic":"Mongolia history","kind":"fact"},{"t":247,"quote":"This historic contribution of the Mongols to the advancement of humankind continues to be recognized by the international community.","topic":"Mongolia history","kind":"fact"},{"t":282,"quote":"our planet is currently confronted with more than 90 armed conflicts, around 30 of which are international","topic":"International security","kind":"number"},{"t":314,"quote":"All of this is weakening the international order established since the Second World War","topic":"International security","kind":"fact"},{"t":352,"quote":"Mongoya underscores the tangible progress made under Secretary General's UN80 initiative to improve the effectiveness and efficiency of the United Nations in response to the challenges of our time and reaffirms its active support for this initiative.","topic":"UN governance","kind":"fact"},{"t":411,"quote":"Believing that reform of the security council should be at the core of broader United Nations reform, Mongolia maintains its principal position in support of expanding the number of both permanent and non-permanent members of the security council, ensuring equitable representation of developing countries in the council and promoting greater openness and transparency in its work.","topic":"UN governance","kind":"fact"},{"t":431,"quote":"Mongolia is one of the 58 countries that have never served as a non-permanent member of the United Nations Security Council.","topic":"Mongolia UN role","kind":"fact"},{"t":452,"quote":"I officially announce from this rostrm today that Mongolia is representing its candidature for a non-permanent seat of the UN Security Council for the term 2048 2049.","topic":"Mongolia UN role","kind":"self_credit"},{"t":486,"quote":"Magoya has been contributing with honor to the efforts on strengthening international peace and security, advancing social and economic development, and protecting human rights, the core pillars of the United For instance, more than three decades ago, in pursuit of its foreign policy to ensure national security through political and diplomatic means, Mongolia declared its territory nuclear Since then, Mongolia has consistently pursued policies and taken","topic":"Mongolia UN role","kind":"fact"},{"t":552,"quote":"having deployed more than 23,000 military and police personnel to hotspots around the world since 2002","topic":"Mongolia military","kind":"number"},{"t":582,"quote":"become one of the few countries to have reached 15% women's participation and representation among its military personnel serving in UN POS since 2006","topic":"Mongolia military","kind":"number"},{"t":600,"quote":"A Mongolian women have made valuable contributions to global peace over the past two decades through their courage, resilience, and ingenuity.","topic":"Women in conflict","kind":"fact"},{"t":649,"quote":"Mongolia has launched several important initiatives in this regard, including serving as one of the founding members of the group of landlock developing countries at the United Nations and the establishment of the international think tank for landlock developing countries in Olympar to translate the vasa program of action into tangible outcomes.","topic":"Women in conflict","kind":"self_credit"},{"t":701,"quote":"the SDG report 2026 shows that only 36% of the sustainable development goals are on track or making moderate progress while 15 progress 15% are regressing","topic":"Mongolia trade","kind":"number"},{"t":723,"quote":"global military expenditure has reached an all-time high of $2.9 trillion US","topic":"Mongolia trade","kind":"number"},{"t":762,"quote":"to the SDG report 2026, Mongolia has achieved 68.8% of the SGS, reflecting the tangible results of our efforts and the progress we have made in recent years.","topic":"Mongolia environment","kind":"number"},{"t":815,"quote":"Mongolia's billion trees national movement goes far beyond tree planting and aforestation. It is a comprehensive nationwide initiative aimed at combating desertification and land degradation, scaling up land restoration, expanding forest resources, protecting soil fertility, water resources and biodiversity, mitigating the adverse impacts of climate change, improving food supply, and creating employment opportunities.","topic":"Mongolia environment","kind":"fact"},{"t":841,"quote":"the United Nations General Assembly resolution initiated by Mongolia proclaiming 2026 as the international year of rangeands and pastoralists provides an opportunity to raise global awareness of the importance of rangeand ecosystems.","topic":"Mongolia environment","kind":"fact"},{"t":876,"quote":"The gathering brought together around 400 herders from 57 countries whose opinions and fruitful discussion of challenges and solutions culminated in the adoption of the olater declaration.","topic":"Mongolia environment","kind":"fact"},{"t":889,"quote":"Moreover, in August, Mongolia successfully hosted the 17th session of the conference of the parties to the United Nations Convention to Combat Desertification in Olatar under the theme restoring land, restoring hope.","topic":"Mongolia environment","kind":"fact"},{"t":949,"quote":"as the presidency of UNCCCD COP 17, Mongolia has advanced the step action agenda built upon three interconnected flagship initiatives.","topic":"Mongolia agriculture","kind":"fact"},{"t":972,"quote":"Particularly we regards the rangeands flagship initiative as a landmark global movement that opens a new chapter in the history of rangeand conservation.","topic":"Mongolia agriculture","kind":"self_credit"},{"t":1048,"quote":"Mongolia held the 11th international conference of the Lambatar dialogue on Northeast Asian security this year.","topic":"Mongolia foreign relations","kind":"fact"},{"t":1058,"quote":"The Obamater dialogue has evolved into a unique platform for strengthening trust and confidence building across Northeast Asia, facilitating multilateral discussions among government delegates and scholars not only on traditional security challenges such as political and disarmament matters, but also on a broad range of issues including energy, infrastructure connectivity, green development, and humanitarian","topic":"Mongolia foreign relations","kind":"fact"},{"t":1194,"quote":"in 2025 at Mongolia's initiative, a United Nations General Assembly resolution proclaiming World Horse Day was adopted","topic":"Mongolia culture","kind":"fact"},{"t":1211,"quote":"last July, the cemetery complexes of the Hunu nobility, Mongoya's first statehood, were inscribed on the UNESCO World Heritage list","topic":"Mongolia culture","kind":"fact"},{"t":1227,"quote":"Mongolia is serving for the first time as a member of the UNESCO World Heritage Committee for the term 2026 2029","topic":"Mongolia culture","kind":"fact"},{"t":1236,"quote":"this year marks the 820th anniversary of the great Mongol Empire, founded by Great Chingishan","topic":"Mongolia culture","kind":"fact"},{"t":1245,"quote":"The United Nations General Assembly resolution adopted on the occasion of the 800 years of Mongolian statethood highly values and emphasizes the contribution of Mongols to the history of humankind by recognizing the richness of nomatic civilization and its important contribution to promoting dialogue and interconnection among all forms of civilization","topic":"Mongolia sovereignty","kind":"fact"},{"t":1297,"quote":"the renowned Mongolist Vladislav Kotvich in his work, Mongols are the promoters of the idea of global peace from the early 14th century noted that Ultitang of the Mongol Empire in his letter sent to King Philip the forth of France in 1305 eloquently underscored the value of harmonious relations among nations and peoples","topic":"Mongolia sovereignty","kind":"fact"},{"t":1339,"quote":"studying the establishment of Pax Mongolica by great Chingisan and his successors as well as the history of its foreign policy and diplomacy offers good practices and enduring lessons","topic":"Mongolia history","kind":"fact"},{"t":1374,"quote":"eight centuries ago laid the foundation for nations to coexist in peace and humanity to flourish","topic":"Mongolia history","kind":"number"},{"t":1400,"quote":"empower the United Nations, the guaranter of world peace and security and a source of hope and trust for the nations of the world into a strong and respected organization capable of bringing Pax Globala.","topic":"UN governance","kind":"fact"}],"promises":[{"t":609,"quote":"In this connection, Mongolia plans to host the second international conference on women's participation in UN peacekeeping operations in Ulatar in 2027.","topic":"Women in conflict","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":null,"text":"We have heard the last speaker in the general debate for this meeting. The next plenary meeting to continue with the general debate will be held immediately following the adjournment of this me. The meeting is adjourned. The six plinary meeting of the general assembly is called to order. The assembly will hear an address by his president of Mongolia. I request protocol to escort his excellency and invite him to to address the assembly. Mr."},{"t":69,"topic":"UN governance","text":"President, Mr. Secretary General, distinguished delegates, ladies and gentlemen, at the outset, I wish to extend my sincere congratulations to Mr. Khalil Rahman on assuming the important role of the president of the 81st session of the United Nations General Assembly and to convey my best wishes for the successful session. This session of the general assembly is convening on the eve of the 65th anniversary of Mongolia's full-fledged membership in the United Nations. In 1961, Mongoya made history by raising its national flag with the golden soybo at the United Nations and becoming the 101st member of the United Nations, the guaranter of global peace and security and the beacon of hope and trust for the world's nations. Mongolia welcomes the convening of the 81st session of the United Nations General Assembly under the theme Restoring Trust, managing transformation, a United Nations that delivers for all, reaffirming its belief in the central role of the United Nations in fostering mutual trust, mutual respect and cooperation among the nations and peoples of the world."},{"t":146,"topic":"UN governance","text":"Mongols say if you do your best, fate will do the rest. The United Nations is an organization based on the trust and commitment of each member state and the UN is strengthened by their dedication and sustained efforts. Therefore, it is incumbent upon us member states to uphold the mission of the United Nations with a sincere heart rather than simply expecting support and assistance. We must remain deeply conscious of our own responsibilities and duties and dedicate our wholehearted efforts to strengthening the United Nations. It is through trust and hope, dedication and commitment and engagement and participation of every member state that we can strengthen the United Nations. A stronger United Nations in turn will deliver more efficiently towards global peace, security and sustainable development, thereby creating conditions for all member states to benefit. As the conflicts and confrontations flash across the world, the walls of distrust rise higher and the chasm of misunderstanding grows deeper."},{"t":209,"topic":"Mongolia history","text":"It is becoming crucial to shape and develop international relations not through a form of multipolarity that risks striving the world toward the vision but through a multi-pillared principle that respects the pluralism inherent in each nation's history, culture, civilization, core national interests and chosen path of development. Eight centuries ago, our ancestors established the great Pax Mongolica, promoting for the first time the idea to the world that nations could mutually recognize one another's values and that peoples of diverse civilizations and faiths could coexist. This historic contribution of the Mongols to the advancement of humankind continues to be recognized by the international community. Let us strengthen multilateral cooperation through the multi-pillar principle inspired by the ideas of Pax Mongolica so that we may restore our trust and hope through shared responsibility, reform the United Nations with a common purpose and build a better, more peaceful world through the strength of our collective action."},{"t":275,"topic":"International security","text":"Mr. President, despite the remarkable heights of development and progress humanity has reached, our planet is currently confronted with more than 90 armed conflicts, around 30 of which are international, demonstrating that global peace and security remain unstable and that geopolitical and geostrategic competition continues to intensify. This results in the disruption of global economic supply chains, a rise in the prices of energy, fuel, raw materials, and food, as well as economic strains on nations around the world. All of this is weakening the international order established since the Second World War, changing the universally recognized norms of international law, and undermining the stability of multilateral relations and Magoya shares the view expressed by United Nations Secretary General Antonio Gutish in his annual report on the work of the organization that in a world marked by turbulence, division and uncertainty, the United Nations is more necessary than ever."},{"t":352,"topic":"UN governance","text":"Hence, Mongoya underscores the tangible progress made under Secretary General's UN80 initiative to improve the effectiveness and efficiency of the United Nations in response to the challenges of our time and reaffirms its active support for this initiative. The effectiveness of the United Nations, the decisiveness of its actions, and the ability of nations to unite their efforts will ultimately depend upon us, the member states. Mongolia is confident that the soon-to-be appointed secretary general will steadfastly uphold the principles and purposes of the United Nations and international law, ensure that the voices and positions of all member states are equally heard and reflected and provide strong leadership in restoring trust and man managing transformation within the UN. Believing that reform of the security council should be at the core of broader United Nations reform, Mongolia maintains its principal position in support of expanding the number of both permanent and non-permanent members of the security council, ensuring equitable representation of developing countries in the council and promoting greater openness and transparency in its work."},{"t":431,"topic":"Mongolia UN role","text":"Mongolia is one of the 58 countries that have never served as a non-permanent member of the United Nations Security Council. Therefore, Mongoya aspires to actively participate in the work of the security council and contribute to finding collective solutions to the problems and challenges facing the international community. In manifestation of this aspiration, I officially announce from this rostrm today that Mongolia is representing its candidature for a non-permanent seat of the UN Security Council for the term 2048 2049. Mr. President, on behalf of the people of Mongolia, I extend my heartfelt gratitude to the United Nations and its system organizations for their valuable contributions to our country's development and progress in their long-standing constructive cooperation over the 65 years since Mongolia's succession to the United Nations as a full-fledged member. Magoya has been contributing with honor to the efforts on strengthening international peace and security, advancing social and economic development, and protecting human rights, the core pillars of the United For instance, more than three decades ago, in pursuit of its foreign policy to ensure national security through political and diplomatic means, Mongolia declared its territory nuclear Since then, Mongolia has consistently pursued policies and taken"},{"t":521,"topic":"Mongolia military","text":"actions to verify the status legally. In this spirit, the United Nations General Assembly adopts on a bianial basis the resolution entitled Mongolia's international security and nuclear weapon free status initiated by Mongolia in 1998. Furthermore, Mongolia has made tangible contributions to global efforts to maintain international peace and security through its active participation in the United Nations peacekeeping operations and other international missions, having deployed more than 23,000 military and police personnel to hotspots around the world since 2002. Even today, our troops are serving in the gang suppression force multinational police and military mission deployed to Mongolia has been actively advancing the implementation of United Nations Security Council resolution 1325 women peace and security and has become one of the few countries to have reached 15% women's participation and representation among its military personnel serving in UN POS since 2006 when Mongolia deployed its first female peacekeeper to the UN mission in Western Sahara."},{"t":600,"topic":"Women in conflict","text":"A Mongolian women have made valuable contributions to global peace over the past two decades through their courage, resilience, and ingenuity. In this connection, Mongolia plans to host the second international conference on women's participation in UN peacekeeping operations in Ulatar in 2027. I am pleased to highlight Mongolia's active leadership within the United Nations in advancing the interests of landlock developing countries, drawing greater international attention to their special needs and unique circumstances and cooperating with these countries to ensure that their voices are heard on the global stage. Mongolia has launched several important initiatives in this regard, including serving as one of the founding members of the group of landlock developing countries at the United Nations and the establishment of the international think tank for landlock developing countries in Olympar to translate the vasa program of action into tangible outcomes."},{"t":667,"topic":"Mongolia trade","text":"It is essential for landlock developing countries to align the program with their national development agendas and make full use of a of available resources and opportunities to accelerate regional integration and cooperation. We also call upon the international community, banks, financial institutions and development partners to provide credible assistance to landlock developing countries through their support and collaboration. Mr. as the deadline for the 2030 agenda for sustainable development approaches, the SDG report 2026 shows that only 36% of the sustainable development goals are on track or making moderate progress while 15 progress 15% are regressing. It is deeply regrettable that according to the latest report of the Stockholm International Peace Research Institute released at this critical time, global military expenditure has reached an all-time high of $2.9 trillion US."},{"t":732,"topic":"Mongolia environment","text":"It is time for all of us to ponder and reflect with common sense on what progress could have been achieved in the development of human society if this huge budget and funds had been spent on tackling pressing issues such as combating global warming and climate change and improving education, health, food security and advancement of women and children. to the SDG report 2026, Mongolia has achieved 68.8% of the SGS, reflecting the tangible results of our efforts and the progress we have made in recent years. As a country experiencing the adverse impacts of climate change firsthand, Mongolia has remained steadfast in contributing to global collective efforts to protect and preserve our natural environment. In this regard, Mongoya is successfully implementing a series of national policies and initi initiatives including the billion trees, food revolution, white gold, blue gold and healthy Mongolian aimed at restoring degraded land, expanding forest resources, protecting soil, water and pasture land, ensuring food supply and security and supporting sustainable rural development."},{"t":815,"topic":"Mongolia environment","text":"Mongolia's billion trees national movement goes far beyond tree planting and aforestation. It is a comprehensive nationwide initiative aimed at combating desertification and land degradation, scaling up land restoration, expanding forest resources, protecting soil fertility, water resources and biodiversity, mitigating the adverse impacts of climate change, improving food supply, and creating employment opportunities. Furthermore, the United Nations General Assembly resolution initiated by Mongolia proclaiming 2026 as the international year of rangeands and pastoralists provides an opportunity to raise global awareness of the importance of rangeand ecosystems. Support the livelihoods of pastoralists, strengthen sustainable food systems, conserve biodiversity, and preserve the cultural heritage of nomadic peoples. In this regard, Mongoya with its millennia old tradition of nomadic pastoralism took the initiative to convene the global pastoralist gathering and conference in Olymp."},{"t":876,"topic":"Mongolia environment","text":"The gathering brought together around 400 herders from 57 countries whose opinions and fruitful discussion of challenges and solutions culminated in the adoption of the olater declaration. Moreover, in August, Mongolia successfully hosted the 17th session of the conference of the parties to the United Nations Convention to Combat Desertification in Olatar under the theme restoring land, restoring hope. Restoring mother nature to its pristine state and creating conditions for future generations to live in a healthy environment with confidence and contentment must be a noble duty of Mother nature and healthy soil are the guarantee of humanity's existence and the foundation of food and water resources, livelihood and sustainable Healthy soil means healthy food and healthy food means healthy people. Therefore, desertification, land degradation, and drought should not be viewed merely as environmental issues, but should be addressed holistically in connection with food supply and security, water resources, livelihood, sustainable development, and global peace and security."},{"t":948,"topic":"Mongolia agriculture","text":"In this spirit, as the presidency of UNCCCD COP 17, Mongolia has advanced the step action agenda built upon three interconnected flagship initiatives. the Rangeland's flagship initiative, the water land nexus initiative and the naturebased solutions for sustainable infrastructure initiative. Particularly we regards the rangeands flagship initiative as a landmark global movement that opens a new chapter in the history of rangeand conservation. This initiative is special in raising global awareness that the protection, sustainable management and restoration of rangelands are of strategic importance for building resilience to climate change, ensuring food security and maintaining balanced ecosystems. The nomatic way of life that we Mongols have inherited and carried forward over thousands of years embodies a comprehensive set of values and wisdom for living in harmony with nature and preserving it in its pristine state."},{"t":1013,"topic":"Mongolia foreign relations","text":"Today we am Mongols aim to share with the world our cultural heritage and the traditional knowledge and experiences gained from living in harmony with nature thereby contributing to enhanced adaptation and resilience to climate Mr. President, Mongoya consistently adheres to the principle of resolving any conflicts through diplomacy and multilateral dialogue while maintaining long-standing friendly relations with the countries of the region. Building on this distinctive advantage, Mongolia held the 11th international conference of the Lambatar dialogue on Northeast Asian security this year. The Obamater dialogue has evolved into a unique platform for strengthening trust and confidence building across Northeast Asia, facilitating multilateral discussions among government delegates and scholars not only on traditional security challenges such as political and disarmament matters, but also on a broad range of issues including energy, infrastructure connectivity, green development, and humanitarian Furthermore, as an active member of the United Nations, Mongolia has contributed to international cooperation to advance gender equality, strengthen women's political participation and leadership, and increase their representation at decisionmaking levels."},{"t":1106,"topic":"Gender equality","text":"In recent years, Mongolia has established a tradition of hosting international events dedicated to women in our country, including the International Conference on strengthening the role of women in [clears throat] peacekeeping in 2022, the Female Foreign Ministers meeting in 2023 and the World Women's Forum in 2024 in collaboration with the United Nations, and the World Women Entrepreneurs Forum in 2025. Hence, I am confident that the World Women Parliamentarians Forum to be held in Oolatar on October 12 to 13 this year will substantially contribute to strengthening women's political leadership and interparliamentary cooperation, thereby advancing gender equality and accelerating progress towards achieving the sustainable development goals. I cordially invite you to participate in this important event at a high level and with broad representation. Magoya will continue to serve as a solid bridge for partnership, cooperation and solidarity in advancing women's social and political leadership and participation at all levels."},{"t":1178,"topic":"Mongolia culture","text":"Mr. President Mongoya has consistently championed and supported numerous initiatives within the international community aimed at preserving and promoting cultural heritage, traditional knowledge, and the shared values of humanity. For instance, in 2025 at Mongolia's initiative, a United Nations General Assembly resolution proclaiming World Horse Day was adopted which recognizes the invaluable contribution of horses to the history, civilization, and socioeconomic development of peoples around the world. Moreover, last July, the cemetery complexes of the Hunu nobility, Mongoya's first statehood, were inscribed on the UNESCO World Heritage list, reflecting international recognition of their historical and cultural significance. It is my pleasure to underline that Mongolia is serving for the first time as a member of the UNESCO World Heritage Committee for the term 2026 2029. Moreover, this year marks the 820th anniversary of the great Mongol Empire, founded by Great Chingishan, men of the Millennium, King of Kings."},{"t":1245,"topic":"Mongolia sovereignty","text":"The United Nations General Assembly resolution adopted on the occasion of the 800 years of Mongolian statethood highly values and emphasizes the contribution of Mongols to the history of humankind by recognizing the richness of nomatic civilization and its important contribution to promoting dialogue and interconnection among all forms of civilization and that nomatic civilization influenced interelia societies across Asia and Europe and in turn absorbed influences from both east and west and a true interchange of human values, the important role in the development of extensive trade networks and the creation of large administrative, cultural, religious and commercial centers. This demonstrates that this historical contributions embodied progressive ideas that could serve as a foundation for today's collective efforts to safeguard peace and stability. For example, the renowned Mongolist Vladislav Kotvich in his work, Mongols are the promoters of the idea of global peace from the early 14th century noted that Ultitang of the Mongol Empire in his letter sent to King Philip the forth of France in 1305 eloquently underscored the value of harmonious relations among nations and peoples in the thoughtful words, \"What could be better than true concord?"},{"t":1329,"topic":"Mongolia history","text":"History is the foundation upon which we reflect on the past, shape the present and build the future and is the memory of our statethood. Scholars advise that studying the establishment of Pax Mongolica by great Chingisan and his successors as well as the history of its foreign policy and diplomacy offers good practices and enduring lessons. Hence we the Mongol people who are guarding the sacred hearth of the great Mongol Empire wish to call upon from this mighty rostrm of the United Nations that if the nations of the world can bring together their efforts it is possible to establish a Pax Globala a global peace embodying the vision of the Pax Mongolica which eight centuries ago laid the foundation for nations to coexist in peace and humanity to flourish. the role and contribution of the United Nations in further strengthening mutual understanding, mutual trust and mutual respect among world nations and in fostering a peaceful world free from war and conflict where all can prosper together are becoming increasingly critical than ever."},{"t":1398,"topic":"UN governance","text":"Therefore, let us work together to empower the United Nations, the guaranter of world peace and security and a source of hope and trust for the nations of the world into a strong and respected organization capable of bringing Pax Globala. May the eternal blue sky bless humankind forever with peace across the world. Thank you for your attention. On behalf of this assembly, I wish thank the president of Mongolia"}],"compare":[{"topic":"UN & its reform","share":0.1908,"mean":0.2048,"rank":99,"others":170},{"topic":"Mongolia","share":0.124,"mean":0.0,"rank":1,"others":0},{"topic":"Gender Equality","share":0.0533,"mean":0.0008,"rank":3,"others":2},{"topic":"International Law & Order","share":0.0522,"mean":0.0604,"rank":87,"others":102},{"topic":"Human Rights","share":0.0492,"mean":0.0084,"rank":17,"others":24}]};
